leaf_data = cells('Leaf costs', 'E30:F32')
leaf_costs = {row[0]: row[1] for row in leaf_data}

rules = {}
for parent, comp, mult in rules_data:
    if parent not in rules:
        rules[parent] = []
    rules[parent].append((comp, mult))

def expand(part):
    if part in leaf_costs:
        return {part: 1}
    totals = {}
    if part in rules:
        for comp, mult in rules[part]:
            sub = expand(comp)
            for k, v in sub.items():
                totals[k] = totals.get(k, 0) + v * mult
    return totals

beacon_leaves = expand('Beacon')
result = [beacon_leaves.get('Alloy', 0), beacon_leaves.get('Bolt', 0), beacon_leaves.get('Wire', 0)]

